import{_ as t,o,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Building your first Flow","description":"Create, configure, test, and activate a Flow step by step.","frontmatter":{"title":"Building your first Flow","description":"Create, configure, test, and activate a Flow step by step."},"headers":[],"relativePath":"en/flows/ersten-flow-bauen.md","filePath":"en/flows/ersten-flow-bauen.md","lastUpdated":1787319236000}'),r={name:"en/flows/ersten-flow-bauen.md"};function s(n,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="building-your-first-flow" tabindex="-1">Building your first Flow <a class="header-anchor" href="#building-your-first-flow" aria-label="Permalink to &quot;Building your first Flow&quot;">​</a></h1><p>This guide builds a complete Flow: as soon as someone submits a sign-up form, a confirmation email goes out and the status in the Grid gets set.</p><p><strong>Prerequisite:</strong> a Grid with a field of type <em>E-Mail</em> and a field of type <em>Single Select</em> (e.g. <code>Status</code> with the options <code>New</code> and <code>Confirmed</code>), plus a <a href="/en/formulare/formular-erstellen">form</a> on it.</p><h2 id="_1-·-create-the-flow" tabindex="-1">1 · Create the Flow <a class="header-anchor" href="#_1-·-create-the-flow" aria-label="Permalink to &quot;1 · Create the Flow&quot;">​</a></h2><ol><li>Open the <strong>Flows</strong> area in the sidebar.</li><li>Click <strong>Create Flow</strong>.</li><li>The Flow is initially named <em>New Flow</em>. Rename it — this pays off quickly once you have several Flows.</li></ol><p>You land in the <strong>Editor</strong>, an empty canvas.</p><h2 id="_2-·-choose-a-trigger" tabindex="-1">2 · Choose a trigger <a class="header-anchor" href="#_2-·-choose-a-trigger" aria-label="Permalink to &quot;2 · Choose a trigger&quot;">​</a></h2><p>The editor asks: <em>When should the Flow start?</em></p><ol><li>Open the <strong>Trigger</strong> tab.</li><li>Choose <strong>Entry via form</strong> — <em>New entry added via form</em>.</li><li>In the step, select the Grid and the form.</li></ol><p>You can click the step or drag it onto the canvas.</p><div class="tip custom-block"><p class="custom-block-title">The trigger determines which data is available</p><p>The choice of trigger decides what all subsequent steps can work with. <em>Entry via form</em> delivers the newly created entry with all its fields — that&#39;s the foundation for everything that follows.</p><p>The trigger can&#39;t simply be swapped out afterward without adjusting the following steps. So think it through first.</p></div><h2 id="_3-·-first-action-send-email" tabindex="-1">3 · First action: send email <a class="header-anchor" href="#_3-·-first-action-send-email" aria-label="Permalink to &quot;3 · First action: send email&quot;">​</a></h2><ol><li>Open the <strong>Actions</strong> tab.</li><li>Choose <strong>Email</strong>.</li><li>Connect the trigger to the new action, if it doesn&#39;t happen automatically.</li><li>Click the action to configure it.</li></ol><p>In the <em>Recipient</em> field, you don&#39;t want a fixed address — you want the one from the entry. Use <strong>Use values from previous steps</strong> and select the trigger&#39;s email field.</p><p>Fill in the subject and body the same way — fixed text and values from the entry can be mixed.</p><div class="tip custom-block"><p class="custom-block-title">Inserting field values</p><p>In text fields, <strong>Ctrl + Space</strong> opens the selection of available Grid fields. The editor shows this hint on its own too.</p></div><h2 id="_4-·-second-action-update-entry" tabindex="-1">4 · Second action: update entry <a class="header-anchor" href="#_4-·-second-action-update-entry" aria-label="Permalink to &quot;4 · Second action: update entry&quot;">​</a></h2><ol><li>In the <strong>Actions</strong> tab, choose the <strong>Update entry</strong> step.</li><li>Connect it after the email action.</li><li>As the entry to update, choose the entry from the trigger.</li><li>Set the <code>Status</code> field to <code>Confirmed</code>.</li></ol><p>The Flow is complete.</p><h2 id="_5-·-test-it" tabindex="-1">5 · Test it <a class="header-anchor" href="#_5-·-test-it" aria-label="Permalink to &quot;5 · Test it&quot;">​</a></h2><p><strong>Test before you go live.</strong> A faulty Flow that reacts to real form submissions sends faulty emails to real people.</p><p>The editor offers several test types. For this case, <strong>With data from the Flow form</strong> — <em>Open the form and test with submitted data</em> — fits.</p><p>Alternatively, <strong>Test Flow</strong> uses the last row of the Grid.</p><p>After the test, check the <strong>History</strong> tab to see whether the run has the status <em>Done</em>. On <em>Error</em>, open it and use <strong>Show error details</strong> to see what went wrong.</p><p>→ <a href="/en/flows/testen">Testing Flows</a></p><h2 id="_6-·-go-live" tabindex="-1">6 · Go live <a class="header-anchor" href="#_6-·-go-live" aria-label="Permalink to &quot;6 · Go live&quot;">​</a></h2><p>If the test runs cleanly, the Flow is ready. From now on it reacts to every real form submission — a newly created Flow is switched on.</p><div class="warning custom-block"><p class="custom-block-title">Verify with a real submission first</p><p>Submit the form yourself once, using your own address. A test run in the editor and a real run don&#39;t always behave identically — especially for fields that are only set via the form.</p></div><p>Using the <a href="/en/flows/was-ist-ein-flow#switching-on-and-off">switch</a> to the right of the <em>Editor</em> and <em>History</em> tabs, you can take the Flow out of service at any time without deleting it.</p><h2 id="working-in-the-editor" tabindex="-1">Working in the editor <a class="header-anchor" href="#working-in-the-editor" aria-label="Permalink to &quot;Working in the editor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Center on all nodes</strong></td><td>Brings all steps into view</td></tr><tr><td><strong>Auto-arrange nodes</strong></td><td>Tidies up the layout</td></tr><tr><td><strong>Show/hide minimap</strong></td><td>Overview for large Flows</td></tr></tbody></table><p>The menu on a step offers <strong>Rename</strong>, <strong>Configure</strong>, <strong>Add connection</strong>, and <strong>Delete</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Rename your steps</p><p>Default names like &quot;Email&quot; stop meaning anything once you have five mail steps. Name steps after their purpose — &quot;Confirmation to attendee&quot;, &quot;Info to team&quot;. It pays off when debugging.</p></div><h2 id="typical-beginner-mistakes" tabindex="-1">Typical beginner mistakes <a class="header-anchor" href="#typical-beginner-mistakes" aria-label="Permalink to &quot;Typical beginner mistakes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th></tr></thead><tbody><tr><td>Flow doesn&#39;t start</td><td>No trigger set, or the trigger points to a different Grid or form</td></tr><tr><td>Flow starts but does nothing</td><td>The steps aren&#39;t connected to each other</td></tr><tr><td>Email goes to no one</td><td>The recipient field contains fixed text instead of a field value</td></tr><tr><td>Update doesn&#39;t take effect</td><td>The step doesn&#39;t update the entry from the trigger</td></tr><tr><td><em>Flow still has errors</em></td><td>A step is incompletely configured</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/flows/trigger">Trigger</a></li><li><a href="/en/flows/aktionen">Actions</a></li><li><a href="/en/flows/daten-zwischen-schritten">Data between steps</a></li><li><a href="/en/flows/testen">Testing Flows</a></li></ul>',37)])])}const g=t(r,[["render",s]]);export{p as __pageData,g as default};
